  description: 'Run two cold-probe agents in separate stages.',
  params: {
    agents: {
      probe1: {
        model: { type: 'string', default: 'default' },
        effort: { type: 'enum', enum: ['low', 'medium', 'high'], default: 'low' },
        timeoutMs: { type: 'number', default: 60000 }
      },
      probe2: {
        model: { type: 'string', default: 'default' },
        effort: { type: 'enum', enum: ['low', 'medium', 'high'], default: 'low' },
        timeoutMs: { type: 'number', default: 60000 }
      }
    }
  }
};

export default async function () {
  phase('Stage 1');
  await agent('probe1', {
    prompt: 'Read notes.txt and report its exact contents.',
    allowedTools: ['Read']
  });
  phase('Stage 2');
  await agent('probe2', {
    prompt: 'Read notes.txt and report its exact contents, then confirm this is the second stage.',
    allowedTools: ['Read']
  });
}

